\r\n      const tab = document.createElement(\'div\');\r\n      tab.className = \'tab\' + (i === 0 ? \' active\' : \'\');\r\n      tab.textContent = cat.label;\r\n      tab.onclick = () => {\r\n        document.querySelectorAll(\'.tab\').forEach(t => t.classList.remove(\'active\'));\r\n        tab.classList.add(\'active\');\r\n        currentTab = cat.temp;\r\n        renderGrid(cat.temp);\r\n      };\r\n      tabs.appendChild(tab);\r\n    });\r\n  }\r\n\r\n  function renderGrid(temp) {\r\n    const filtered = temp ? allDrinks.filter(d => d.temperature === temp) : allDrinks;\r\n    const grid = document.getElementById(\'grid\');\r\n    \r\n    if (filtered.length === 0) {\r\n      grid.innerHTML = \'<p style="text-align:center;color:#aaa;grid-column:span 2;padding:40px">لا يوجد منتجات</p>\';\r\n      return;\r\n    }\r\n\r\n    grid.innerHTML = filtered.map(d => `\r\n      <div class="card \${(cart[d.id]||0)>0?\'in-cart\':\'\'}" id="card-\${d.id}">\r\n        <div class="emoji">\${emojis[d.temperature]||\'🍹\'}</div>\r\n        <div class="name">\${d.name}</div>\r\n        <div class="price">\${d.price} ج</div>\r\n        \${(cart[d.id]||0) === 0\r\n          ? `<button class="add-btn" onclick="addToCart(\${d.id})">إضافة</button>`\r\n          : `<div class="qty-ctrl">\r\n              <button class="qty-btn" onclick="removeFromCart(\${d.id})">−</button>\r\n              <span class="qty-num">\${cart[d.id]}</span>\r\n              <button class="qty-btn" onclick="addToCart(\${d.id})">+</button>\r\n            </div>`\r\n        }\r\n      </div>\r\n    `).join(\'\');\r\n  }\r\n\r\n  function addToCart(id) {\r\n    cart[id] = (cart[id] || 0) + 1;\r\n    updateCartBar();\r\n    renderGrid(currentTab);\r\n  }\r\n\r\n  function removeFromCart(id) {\r\n    cart[id] = (cart[id] || 0) - 1;\r\n    if (cart[id] <= 0) delete cart[id];\r\n    updateCartBar();\r\n    renderGrid(currentTab);\r\n  }\r\n\r\n  function updateCartBar() {\r\n    const bar = document.getElementById(\'cart-bar\');\r\n    const ids = Object.keys(cart);\r\n    if (ids.length === 0) { bar.classList.remove(\'visible\'); return; }\r\n    bar.classList.add(\'visible\');\r\n\r\n    let total = 0, count = 0;\r\n    ids.forEach(id => {\r\n      const drink = allDrinks.find(d => d.id == id);\r\n      if (drink) { total += drink.price * cart[id]; count += cart[id]; }\r\n    });\r\n    document.getElementById(\'cart-count\').textContent = count;\r\n    document.getElementById(\'cart-price\').textContent = total.toFixed(0);\r\n  }\r\n\r\n  async function sendOrder() {\r\n    const btn = document.getElementById(\'send-btn\');\r\n    btn.disabled = true;\r\n    btn.textContent = \'جاري الإرسال...\';\r\n\r\n    const items = Object.keys(cart).map(id => {\r\n      const drink = allDrinks.find(d => d.id == id);\r\n      return { drink_id: parseInt(id), drink_name: drink.name,\r\n               qty: cart[id], price: drink.price };\r\n    });\r\n\r\n    try {\r\n      await fetch(\'/api/order\', {\r\n        method: \'POST\',\r\n        headers: { \'Content-Type\': \'application/json\' },\r\n        body: JSON.stringify({\r\n          tableId: TABLE_ID,\r\n          tableName: TABLE_NAME,\r\n          note: document.getElementById(\'note\').value,\r\n          items\r\n        })\r\n      });\r\n\r\n      document.getElementById(\'menu-page\').style.display = \'none\';\r\n      document.getElementById(\'thanks-page\').style.display = \'block\';\r\n    } catch(e) {\r\n      alert(\'فشل إرسال الطلب، حاول مرة تانية\');\r\n      btn.disabled = false;\r\n      btn.textContent = \'➤ أرسل الطلب\';\r\n    }\r\n  }\r\n\r\n  function newOrder() {\r\n    cart = {};\r\n    document.getElementById(\'note\').value = \'\';\r\n    document.getElementById(\'menu-page\').style.display = \'block\';\r\n    document.getElementById(\'thanks-page\').style.display = \'none\';\r\n    renderGrid(currentTab);\r\n  }\r\n\r\n  loadMenu();\r\n</script>\r\n</body>\r\n</html>\r\n': '\r\n<!DOCTYPE html>\r\n<html lan